pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // First, send 1 wei directly to trigger receive() (increments depositsCount in reference, not in buggy)
        address(c).call{value: 1 wei}("");
        // Now sendMoney with 1 wei to address(this) - sendMoney doesn't trigger receive, but check depositsCount later
        vm.prank(c.owner());
        c.sendMoney(address(this), 1 wei, "");
        // After these two operations:
        // Reference: depositsCount = 1 (from receive) + 0 (sendMoney doesn't call receive) = 1? Wait, let's recalc.
        // Actually sendMoney does a .call, which triggers receive on the target if it's a contract with receive.
        // address(this) is the test contract, which has no receive, so no increment.
        // So reference: depositsCount = 1 (from direct call), buggy: 0.
        // To make it 2 vs 1: Do another direct call to receive first.
        // Let's do two direct calls to receive then sendMoney.
        address(c).call{value: 1 wei}("");
        address(c).call{value: 1 wei}("");
        vm.prank(c.owner());
        c.sendMoney(address(this), 1 wei, "");
        // Reference: depositsCount = 2 (from two receives) = 2, buggy: 0.
        // Actually we want a difference where both get some increments but one missing.
        // Simpler: one receive + one sendMoney to a contract that has receive (like C itself) to trigger another increment.
        // Let's do: one direct receive, then sendMoney to c (which has receive).
        address(c).call{value: 1 wei}("");
        vm.prank(c.owner());
        c.sendMoney(address(c), 1 wei, "");  // This triggers receive again on c
        // Reference: depositsCount = 2 (first direct, then via sendMoney's internal call), buggy: 1 (only first direct, second doesn't increment)
        assertTrue(c.depositsCount() == 2);
    }
}

