pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = address(this);
        vm.deal(owner, 1 ether);
        vm.prank(owner);
        // First call to sendMoney triggers receive with value 0
        c.sendMoney{value: 0}(address(0x123), 0, "");
        // After this call, reference: depositsCount == 1; bug: depositsCount == type(uint256).max
        // Second call to sendMoney will trigger receive again
        // In reference, (depositsCount + 1) >= depositsCount holds (2 >= 1), success -> depositsCount becomes 2
        // In bug, (type(uint256).max + 1) >= type(uint256).max => 0 >= type(uint256).max => false => REVERT
        // So we wrap the second call in try/catch to detect revert
        bool ok;
        try c.sendMoney{value: 0}(address(0x456), 0, "") {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: second call succeeds (ok == true)
        // Bug: second call reverts (ok == false)
        assertTrue(ok);
    }
}

