pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // deploy an attacker contract that reenters withdrawAll on receive
        address owner = address(this);
        // deploy via new: we need a contract that will reenter
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));
        // fund owner
        vm.deal(owner, 10 ether);
        // owner calls sendMoney to attacker with 1 ether
        vm.prank(owner);
        c.sendMoney{value: 1 ether}(address(attacker), 1 ether, "");
        // now attacker's receive() was called, which reentered withdrawAll
        // In the reference (transfer), the reentrancy fails because transfer only sends 2300 gas
        //   and attacker's receive() cannot call withdrawAll again; the contract balance becomes 0
        // In the buggy (call), the reentrancy succeeds and withdrawAll is called again
        //   but since owner already called withdrawAll, the second withdrawAll reverts because
        //   the modifier onlyOwner passes (msg.sender is attacker which is not owner).
        //   Actually the attacker's receive() is called during sendMoney's call, and the call is
        //   made by the original sendMoney which is called by owner, so msg.sender for attacker's
        //   receive() is the C contract itself (since it's the one doing the call).
        //   Then attacker tries to call c.withdrawAll() which requires onlyOwner: msg.sender would be attacker, not owner, so it reverts.
        //   The buggy withdraw uses call which forwards all gas, so the reentrancy attempt reverts
        //   and the entire sendMoney reverts. So balance(c) remains 1 ether.
        // In the reference, transfer only gives 2300 gas, so attacker's receive() cannot even call withdrawAll
        //   (it would run out of gas or revert), so sendMoney succeeds and balance(c) becomes 0.
        // So after the call, c's balance differs: reference has 0, buggy has 1 ether.
        assertTrue(address(c).balance == 0 ether);
    }
}

contract ReentrantAttacker {
    C target;
    constructor(address _target) {
        target = C(_target);
    }
    receive() external payable {
        // try to reenter withdrawAll
        target.withdrawAll();
    }
}

