pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = address(this);
        vm.deal(owner, 10 ether);

        // Deploy a malicious contract that reenters withdrawAll on receiving ether
        MaliciousReentrancy attacker = new MaliciousReentrancy(address(c));
        address attackerAddr = address(attacker);
        vm.deal(attackerAddr, 1 ether);

        // Owner calls sendMoney to attacker with 1 ether, triggering reentrancy
        vm.prank(owner);
        c.sendMoney(attackerAddr, 1 ether, "");

        // After the transaction, owner balance differs:
        // Reference: transfer in withdrawAll prevents reentrancy, so owner gets 1 ether back
        // Buggy: reentrancy drains all contract balance (including the 1 ether just sent) to owner
        uint256 ownerBalanceReference = 10 ether - 1 ether + 1 ether; // 10 ether (no extra withdrawal)
        uint256 ownerBalanceActual = address(owner).balance;
        assertTrue(ownerBalanceActual == ownerBalanceReference, "Owner balance should equal reference");
    }
}

contract MaliciousReentrancy {
    C public target;
    constructor(address _target) {
        target = C(_target);
    }
    receive() external payable {
        // Reenter withdrawAll to drain all ether
        target.withdrawAll();
    }
    function attack() external payable {
        target.sendMoney(address(this), msg.value, "");
    }
}

